declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVariable\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\Sql\SqlTemplate;
use Civi\Lughauth\Features\Document\TemplateVariable\Application\Usecase\Create\TemplateVariableCreateUsecase;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableUidVO;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableCodeVO;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableTenantVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableTypeVO;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableValueVO;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableVersionVO;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\TemplateVariable\Application\Usecase\Create\TemplateVariableCreateParams;
use Civi\Lughauth\Features\Document\TemplateVariable\Application\Usecase\Create\TemplateVariableCreateResult;

class TemplateVariableCreateController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly SqlTemplate $sql,
        private readonly TemplateVariableCreateUsecase $createUsecase,
    ) {
    }
    #[OA\Post(
        path: "/api/document/template-variable",
        tags: ["Template variable"],
        description:"Create",
        requestBody: new OA\RequestBody(content: new OA\JsonContent(type: "object", ref:"#/components/schemas/TemplateVariableApiDTO")),
        responses: [
              new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/TemplateVariableApiDTO")),
              new OA\Response(response: 422, description: "Constraint error"),
          ]
    )]
    public function create(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Create Template variable");
        $span = $this->startSpan("Create Template variable");
        $this->sql->begin();
        try {
            $value = $this->readTemplateVariable($request);
            $result = $this->createUsecase->create($value);
            $this->sql->commit();
            $value = $this->mapTemplateVariable($request, $result);
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(201)
              ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $this->sql->close();
            $span->end();
        }
    }

    private function readTemplateVariable(ServerRequestInterface $request): TemplateVariableCreateParams
    {
        $this->logDebug("Read entity for Template variable");
        $span = $this->startSpan("Read entity for Template variable");
        try {
            $parsed = $request->getParsedBody() ?? [];
            $body = is_array($parsed) ? $parsed : get_object_vars($parsed);
            $errorsList = new ConstraintFailList();
            $value = new TemplateVariableCreateParams();
            $valueUid = TemplateVariableUidVO::tryFrom($body['uid'] ?? null, $errorsList);
            if (null !== $valueUid) {
                $value->uid($valueUid);
            }
            $valueCode = TemplateVariableCodeVO::tryFrom($body['code'] ?? null, $errorsList);
            if (null !== $valueCode) {
                $value->code($valueCode);
            }
            if (in_array('tenant', array_keys($body))) {
                $valueTenant = TemplateVariableTenantVO::tryFrom(isset($body['tenant']['$ref']) ? new TenantRef($body['tenant']['$ref']) : null, $errorsList);
                if (null !== $valueTenant) {
                    $value->tenant($valueTenant);
                }
            }
            $valueType = TemplateVariableTypeVO::tryFrom($body['type'] ?? null, $errorsList);
            if (null !== $valueType) {
                $value->type($valueType);
            }
            $value->value(TemplateVariableValueVO::tryFrom($body['value'] ?? null, $errorsList));
            $value->version(TemplateVariableVersionVO::tryFrom($body['version'] ?? null, $errorsList));
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            return $value;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function mapTemplateVariable(ServerRequestInterface $request, TemplateVariableCreateResult $value): TemplateVariableApiDTO
    {
        $this->logDebug("Map entity to output dto for Template variable");
        $span = $this->startSpan("Map entity to output dto for Template variable");
        try {
            $tenant = $value->getTenant();
            $dto = new TemplateVariableApiDTO();
            $dto->uid = $value->getUid();
            $dto->code = $value->getCode();
            $dto->tenant = $tenant ? ['$ref' => $tenant->uid()] : null;
            $dto->type = $value->getType();
            $dto->value = $value->getValue();
            $dto->enabled = $value->isEnabled();
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
